// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= type(uint96).max);
        Recipient recipient = new Recipient();
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(recipient).balance;
        c.withdrawAll(address(recipient));
        uint256 balanceAfter = address(recipient).balance;
        assertTrue(balanceAfter == balanceBefore + amount);
    }
}
contract Recipient {
    receive() external payable {}
}
